internal object DuaMaiDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_praising_someone" to DuaText("जखन कोनो लोकक प्रशंसा करैत छी", "हम एहि तरहेँ मानैत छी, आ अल्लाह हुनकर हिसाबदार छथि, आ हम अल्लाह के सामने ककरो पवित्रताक आश्वासन नहि दैत छी।", "जखन कोनो लोकक प्रशंसा करैत छी, अतिरंजित करबाक बदला।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम प्रशंसाक ई शिष्टाचार सिखौलनि।"),
        "dua_being_praised" to DuaText("जखन अहाँ प्रशंसा प्राप्त करैत छी", "ऐ अल्लाह, हमरा ओहि बातक हिसाब नहि दियौक जे ओ सभ कहैत अछि आ जे बात ओ सभ नहि जनैत अछि तकरा हमरा क्षमा कऽ दियौक।", "अपन प्रशंसा सुनबा पर-साथी (आर. ए.) क अभ्यास।", "प्रशंसा कयल जाए पर अहंकारसँ बचबाक एकटा तरीका।"),
        "dua_non_muslim_sneezes" to DuaText("जखन कोनो गैर-मुसलमान छिँकता अछि।", "अल्लाह अहाँक मार्गदर्शन करय आ अहाँक काज ठीक करे।", "जखन कोनो गैर-मुसलमान छिङ्कि कऽ'अल्हमदुलिल्लाह'कहैत अछि।", "यहूदी लोकनि पैगम्बर सल्लल्लाहु अलैहि वसल्लमक लग एहि आशा मे छिङ्कि जायत जे ओ'यारहमुकल्लाह'कहैत छथि, आ ओ ई कहैत छथि।"),
        "dua_reply_ahl_kitab_salam" to DuaText("पुस्तकक लोकसभक सलामकेँ उत्तर देब।", "आ अहाँ पर।", "जखन किताबक लोक नमस्कार करैत छथि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के निर्देश।"),
        "dua_fasting_invited" to DuaText("उपवास करैत काल जखन आमंत्रित कयल गेल छल", "हम उपवास करैत छी।", "जखन उपवासक समय आमंत्रित कयल जाइत अछि, वा जखन कोनो व्यक्ति अहाँ सँ झगड़ा करैत अछि।", "यदि उपवास करयवला व्यक्ति कोनो निमंत्रण स्वीकार करैत अछि तँ ओकरा मेजबानक लेल प्रार्थना करबाक चाही।"),
        "dua_for_who_gave_drink" to DuaText("जे हमरा खिला रहल अछि", "ओ अल्लाह, जे हमरा खयौलऽ वला केँ खिलाउ आ जे हमरा पीयबाक लेल तैयार कयलक ओकरा पीऔ।", "जे केओ अहाँकेँ खयबाक वा पिबबाक लेल दैत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अल-मक्दाद (रा.) क लेल ई दुआ बनौलनि।"),
        "dua_eid_greeting" to DuaText("ईद की बधाई", "अल्लाह हमरा सँ आ अहाँ सँ (नीक काज) स्वीकार करू।", "ईद के दिन एक दोसर के लेल-कुलीन साथी (आर. ए.) के प्रथा।", "ई बात साथी लोकनि ईद पर भेँट करैत कहलनि।"),
        "dua_wedding_night" to DuaText("निकाहक बाद दुल्हन लेल", "ऐ अल्लाह, हम अहां सँ ओकर नीक आ नीक स्वभावक प्रार्थना करैत छी जाहि सँ अहाँ ओकरा उत्पन्न कयलहुँ, आ हम अहाँ सँ ओकर अधलाह आ ओहि दुष्ट स्वभावसँ शरण चाहैत छी जाहि सँ अहाँ ओकरा उत्पन्न कयलहुँ।", "निकाहक बाद पत्नीक कपार पर हाथ राखि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के शिक्षा-विवाह मे आशीर्वाद।"),
        "dua_istisqa_ibadak" to DuaText("अपन सेवक आ जानवरसभकेँ पानी दियौक।", "ऐ अल्लाह, अपन दास सभ केँ आ अपन पशु-जन्तु सभ केँ पानि दियौक, अपन दया फैला दियौक आ अपन मृत भूमि केँ जीवन दियौक।", "बरखा (इस्तिस्का) के लेल माँगैत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बरखा लेल ई दुआ बनौलनि।"),
        "dua_seeing_clouds" to DuaText("आन्हर मेघ देखनाय।", "ऐ अल्लाह, हम अहाँ मे ओकर बुराई सँ शरण चाहैत छी।", "आकाशमे आन्हर मेघ देखलापर; जँ बरखा होइत अछि तँ'अल्लाहुम्मा सैय्यिबान नफिया'कहि लिअ।", "मेघ देखि पैगम्बर सल्लल्लाहु अलैहि वसल्लम अपन काज छोड़ि एहि दुआ केँ करैत छलाह।"),
        "dua_jamarat" to DuaText("जमारत पर पथराव", "अल्लाह सबसँ महान छथि।", "प्रत्येक कंकड़ फेकल गेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम प्रत्येक कंकड़क संग तकबीर कहलनि, तकर बाद पहिल आ दोसर जमराहक बाद किबला के सामना कऽ एकटा लम्बा दुआ कयलनि।"),
        "dua_rabbi_ainni" to DuaText("हे हमर प्रभु, हमर सहायता करू, हमर विरोध नहि करू।", "हे हमर प्रभु, हमरा सहायता करू आ हमरा विरुद्ध दोसरक सहायता नहि करू, हमरा विजय प्रदान करू आ हमरा पर दोसरक विजय नहि करू, हमरा लेल योजना बनाउ आ हमरा विरुद्ध योजना नहि बनाउ, हमरा मार्गदर्शन करू आ मार्गदर्शन करू आ जे हमरा पर अन्याय करय ओकरा विरुद्ध हमर सहायता करू।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम (स. अ.) क एक व्यापक दुआ।", "एकटा दुआ जे धर्म आ एहि संसारमे हर मदति जुटबैत अछि।"),
        "dua_ati_nafsi_taqwaha" to DuaText("हमर आत्माक तकवा करू।", "ऐ अल्लाह, हमर प्राण केँ एकर धर्मपरायणता प्रदान करू आ एकरा शुद्ध करू, कारण अहाँ एकरा शुद्ध करबाक लेल सबसँ नीक छी। अहाँ एकर संरक्षक आ मालिक छी।", "स्वयंमे सुधार आ शुद्धिक लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि दुआ केँ बनबैत छलाह।"),
        "dua_iqsim_lana_khashyatik" to DuaText("हमरा सभ केँ अहाँक एहन भय दे।", "ऐ अल्लाह, हमरा सभ केँ अहाँक भय दे जे अहाँ हमरा सभक बीच आबि कऽ अहाँक आज्ञा नहि मानब, हमरा सभ केँ अहाँक स्वर्ग मे लऽ जयबाक लेल पर्याप्त आज्ञाकारिता, आ एहि दुनियाक विपत्तिकेँ हमरा लेल आसान बनेबाक लेल पर्याप्त निश्चितता। जाबत धरि अहाँ हमरा सभ केँ जीवित राखब, आ ओकरा हमरा सभ केँ चिरस्थायी बनाब, ताबत धरि अपना सभ केँ अपन श्रवण, अपन दृष्टि आ अपन शक्तिक आनंद लेब। जे हमरा पर अन्याय करैत अछि, तकरा सभ सँ बदला लिअ, हमर शत्रु सभ सँ सहायता करू, हमर विपत्तिकेँ हमर धर्म मे नहि रहय दियौक, एहि संसार केँ हमर सबसँ पैघ चिन्ता वा हमर ज्ञानक सीमा नहि बना दियौक, आ हमरा सभ पर एहन लोक नहि लगा दियौक जे हमरा सभ पर दया नहि करय।", "जखन कोनो सभा सँ उठैत छथि तखन पैगम्बर सल्लल्लाहु अलैहि वसल्लम शायद ही कखनो ई दुआ बने बिना उठैत छथि।", "धर्म, एहि संसार आ आखिरतक भलाइक लेल एकटा व्यापक दुआ।"),
        "dua_infani_bima_allamtani" to DuaText("अहाँ हमरा जे सिखौलनि, ओकरा सँ हमरा लाभ पहुँचाउ।", "ऐ अल्लाह, जे किछु अहाँ हमरा सिखौलनि, से हमरा लाभ पहुँचाउ, आ जाहि सँ हमरा लाभ होयत, से सिखाउ आ ज्ञान बढ़ाउ।", "ज्ञान प्राप्त करैत काल वा अध्ययनसँ पहिने।", "लाभकारी ज्ञान आ ओहि पर कार्य करबाक लेल एक दुआ।"),
        "dua_jar_su" to DuaText("एकटा खराब पड़ोसीसँ शरण", "ऐ अल्लाह, हम स्थायी निवासक स्थान पर एकटा दुष्ट पड़ोसीसँ अहाँक शरण चाहैत छी, कारण पड़ोसी यात्रा पर चलैत अछि।", "कोनो खराब पड़ोसीसँ सुरक्षा लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि सँ शरण लेबाक आदेश देलनि।"),
        "dua_ishfi_abdak" to DuaText("एकटा बीमार व्यक्तिक स्वास्थ्यलाभ लेल", "ऐ अल्लाह, अहाँक सेवककेँ ठीक करू जाहि सँ ओ अहाँक लेल कोनो दुश्मनक सामना कऽ सकय वा अहाँक लेल प्रार्थना करय लेल चलि सकय।", "बीमार व्यक्ति के लेल जखन ओ हुनका लग अबैत छथि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बीमारलोकनि लेल ई कहैत सिखौलनि।"),
        "dua_la_mania" to DuaText("अहाँ जे दैत छी ओकरा कोनो नहि रोकि सकैत अछि।", "ककरो पूज्य-पूजाक अधिकार नहि अछि, सिवाय अल्लाह के, बिना साझीदारक। शासन हुनकर अछि, प्रशंसा हुनकर अछि, आ ओ सब चीज पर अधिकार अछि। हे अल्लाह, जे किछु अहाँ दैत छी से कोनो रोक नहि सकैत अछि, आ जे किछु अहाँ रोकैत छी से कोनो नहि दऽ सकैत अछि, आ धनीक धन अहाँक विरुद्ध कोनो लाभ नहि कऽ सकैत अछि।", "फरजी नमाज़क नमाज़क बाद।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम प्रत्येक फरजी नमाज़क बाद ई कहलनि।"),
        "dua_slaughtering" to DuaText("जखन कोनो जानवरकेँ मारि देल जाइत अछि", "अल्लाह के नाम पर, आ अल्लाह सबसँ महान छथि।", "जखन कोनो जानवरक बलि देल जाइत अछि वा मारि देल जाइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बलि देबाक समय बिस्मिल्लाह आ तकबीरक बात कयलनि।"),
        "dua_undressing" to DuaText("कपड़ा उतारैत समय", "अल्लाह के नाम पर।", "कपड़ा उतारिबा (घुसल वा बदलबाक लेल)।", "ई जिन्नक आँखि आ व्यक्तिक गुप्तांगक बीच एकटा पर्दा बनि जाइत अछि।"),
        "dua_ilbas_jadidan" to DuaText("कोनो गोटेकेँ नव कपड़ामे देखल जा रहल अछि।", "नव पहिरू, प्रशंसनीय जीउ आ शहीद भऽ मरि जाउ।", "एकटा मुसलमान भाइकेँ नव वस्त्र मे देखलासँ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम उमर (र) केँ नव वस्त्र पहिरैत देखिकऽ ई दुआ कयलनि।"),
        "dua_hajj_la_riya" to DuaText("प्रदर्शनसँ मुक्त हज", "ऐ अल्लाह, (एकरा) एकटा हज बनाउ जकर कोनो प्रदर्शन नहि होअय आ कोनो ख्यातिक खोज नहि होअय।", "हज्जक इरादा करैत समय ईमानदारीक लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम हज्जक समय ई दुआ कयलनि।"),
        "dua_q_muslimayni_laka" to DuaText("इब्राहिम आ इस्माइल (ए. एस.) क दुआ-हमरा सभ केँ आज्ञाकारी बनाउ।", "हमर प्रभु, हमरा सभ केँ अहाँक आ अपन सन्तान मे सँ एक एहन जाति बनाउ जे अहाँक अधीन हो। हमरा सभक पूजा-अर्चना के विधि देखाउ आ हमर पश्चाताप स्वीकार करू। निश्चय ही अहाँ पश्चाताप के अग्रदूत, दयावान छी।", "अपन आ अपन वंशज सभक लेल समर्पणक दुआ।", "दुआ काबा के निर्माण के दौरान बनाओल गेल छल।"),
        "dua_q_iftah_baynana" to DuaText("शुऐब (ए. एस.) क दुआ-हमरा सभक बीच न्यायकर्ता", "हमर प्रभु, हमरा सभक आ हमर सभक बीच सत्यक संग न्याय करू, आ अहाँ सभ श्रेष्ठ न्यायकर्ता छी।", "सत्य आ असत्यक बीच निर्णय लेल।", "शुऐब (अ. स.) क दुआ जखन हुनकर लोक हुनका अस्वीकार कऽ देलक।"),
        "dua_q_la_akuna_zahiran" to DuaText("मूसा (ए. एस.) क दुआ-अपराधीक सहायक कखनो नहि।", "हे हमर प्रभु, अहाँ हमरा पर जे कृपा कयलहुँ, हम ओकरा सँ अपराधीक सहायता नहि करब।", "अल्लाह के बरकत के लेल आभार आ अधर्मी के मदद नहि करै के प्रतिज्ञा।", "पश्चातापक बाद मूसा (ए. एस.) क प्रतिज्ञा।"),
        "dua_q_nuh_unsurni" to DuaText("नूह (अ. स.) क दुआ-हमर सहायता करू, ओ सभ हमरा मना करैत छथि।", "हे हमर प्रभु, हमरा सहायता करू, कारण ओ सभ हमरा पर विश्वास नहि कयने अछि।", "जखन लोक अहाँ सँ इनकार करैत अछि आ सत्य केँ अस्वीकार करैत अछि।", "नूह (अ. स.) क दुआ, जकर उत्तर देल गेल।"),
        "dua_q_ihkum_bil_haqq" to DuaText("हे हमर प्रभु, सत्यक संग न्याय करू।", "हे हमर प्रभु, सत्यक संग न्याय करू। आ हमर प्रभु अत्यन्त दयावान छथि, जिनका अहाँ सभ द्वारा वर्णित बात सभक विरुद्ध सहायता माँगी जाइत अछि।", "झूठ आ झूठक आरोपक सामनामे।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ दुआ सिखायल गेल।"),
        "dua_ghalabatid_dayn" to DuaText("ऋण आ शत्रु सभक पतनसँ शरण", "ऐ अल्लाह, हम अहाँ मे कर्ज सँ अभिभूत होयबाक, दुश्मन द्वारा पराजित होयबाक आ दुश्मनक हर्षोल्लास सँ शरण चाहैत छी।", "ऋणक बोझ आ शत्रु सभक प्रभुत्वसँ सुरक्षा।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि बात सभ सँ शरण लैत छलाह।"),
        "dua_faqr_qillah_dhillah" to DuaText("गरीबी आ अपमानसँ शरण", "ऐ अल्लाह, हम अहाँ मे गरीबी, कमी आ अपमान सँ, आ दोसर पर अन्याय करबासँ वा अन्याय सँ शरण चाहैत छी।", "कष्ट, इच्छा आ अपमानसँ सुरक्षित रहनाय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम द्वारा सिखायल गेल आश्रय।"),
        "dua_five_things_new_muslim" to DuaText("क्षमा करू, दया करू, मार्गदर्शन करू, उपचार करू, प्रदान करू।", "हे अल्लाह, हमरा क्षमा करू, हमरा पर दया करू, हमर मार्गदर्शन करू, हमरा कल्याण करू आ हमर भरण-पोषण करू।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम नव मुसलमानसभ केँ नमाज़क संग ई दुआ सेहो सिखौलनि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि, \"ई शब्द अहाँ सभक लेल ई संसार आ आख़िरतकेँ एकत्रित करैत अछि।"),
        "dua_ruku_laka_raka_tu" to DuaText("रुकू मे-हम अहाँ के सामने झुकल छी", "हे अल्लाह, हम अहाँ केँ नमन कयलहुँ, अहाँ पर विश्वास कयलहुँ आ अहाँ के अधीन कयलहुँ। हमर श्रवण, हमर दृष्टि, हमर मन, हमर हड्डी आ हमर नस अहाँ सँ पहिने विनम्र अछि।", "रुकूमे (विशेष रूपसँ स्वैच्छिक प्रार्थनामे)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम रुकू मे ई पाठ कयलनि।"),
        "dua_sujood_laka_sajadtu" to DuaText("सुजूद मे-हम अहाँ के लेल प्रोस्ट्रेटेड कयलहुँ।", "ऐ अल्लाह, हम अहाँ केँ सिजदा कयलहुँ, अहाँ पर विश्वास कयलहुँ आ अहाँ के अधीन कयलहुँ। हमर मुँह हुनका सिजदा कयल गेल अछि जे एकरा बनाए, आकार देल आ एकर श्रवण आ दृष्टि उत्पन्न कयलक। धन्य अछि अल्लाह, जे श्रेष्ठ निर्माता छथि।", "सुजूदमे (विशेष रूपसँ स्वैच्छिक प्रार्थनामे)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सुजूद मे ई पाठ कयलनि।"),
        "dua_ruku_sujood_subhanaka" to DuaText("महिमावान छी, हमर प्रभु, क्षमा करू।", "महिमावान छी अहाँ, हे हमर प्रभु, आ प्रशंसा अहाँ पर हो। हे अल्लाह, हमरा क्षमा करू।", "रुकू आ सुजूद मे।", "आयशा (रा.): पैगम्बर सल्लल्लाहु अलैहि वसल्लम अक्सर ई बात रुकू आ सुजूद मे कहैत छलाह।"),
        "dua_q_musa_li_akhi" to DuaText("मूसा (अ. स.) क दुआ-हमरा आ हमर भाइकेँ क्षमा कऽ दियौक।", "हे हमर प्रभु, हमरा आ हमर भाइकेँ क्षमा कऽ दियौक आ हमरा सभ केँ अपन दयामे सम्मिलित करी, कारण अहाँ पर दयाशील सभ मे सँ अहाँ बहुत दयालु छी।", "अपन आ अपन भाय वा प्रियजनक लेल क्षमा।", "हारून (ए. एस.) के लेल मूसा (ए. एस.) के दुआ।"),
        "dua_q_ufawwidu_amri" to DuaText("हम अपन मामला अल्लाहकेँ सौंपैत छी।", "आ हम अपन काज अल्लाहकेँ सौंपैत छी। निश्चयहि अल्लाह अपन दाससभकेँ सभ देखि रहल छथि।", "जखन लोक अहाँक विरोध करैत छथि आ मामला अल्लाह पर छोड़ि देल जाय।", "फेरौनक लोक सभक विश्वासीक शब्द-तखन अल्लाह हुनका हुनक दुष्ट षड्यंत्रसँ बचौलनि।"),
        "dua_q_hawariyyun" to DuaText("शिष्यसभक दुआ-गवाह सभक संग हमरा सभ केँ रिकॉर्ड करू।", "4 \"हे हमर प्रभु, अहाँ जे किछु अवतरित कयलहुँ ताहि पर अपना सभ विश्वास कयलहुँ और रसूल (सल्लल्लाहु अलैहि वसल्ल) केँ अनुसरण कयलहुँ, तेँ अपना सभ केँ गवाह बना लिअ।", "विश्वास मे दृढ़ता आ रसूल के अनुसरण मे दृढ़ता के लेल।", "ईसा (ए. एस.) क शिष्यसभक दुआ।"),
        "dua_q_la_tukhzini" to DuaText("इब्राहिम (अ. स.) क दुआ-हमरा अपमानित नहि करू।", "आ जाहि दिन ओ सभ जी उठल छथि, ओहि दिन हमरा अपमानित नहि करू।", "पुनरुत्थानक दिन अपमानसँ सुरक्षित रहबाक लेल।", "आख़िरतक लेल इब्राहिम (अ. स.) क दुआ।"),
        "dua_iftar_laka_sumtu" to DuaText("इफ्तार-अहाँक लेल हम फुरसत लेलहुँ।", "ऐ अल्लाह, हम अहाँक लेल व्रत रखलनि आ अहाँक रोजी-रोटी सँ अपना व्रत तोड़लनि।", "व्रत तोड़ैत समय (प्रसिद्ध इफ्तार दुआ)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई इफ्तारमे ई कहलनि। ई एकटा मुर्सल कथन अछि जे अन्य आख्यानसँ मजबूत होइत अछि; इफ्तारमे एकर पाठ करब हनाफी आ बहुमतक प्रथा अछि।"),
        "dua_iftar_ibn_umar" to DuaText("इफ्तार-अपन विशाल दयासँ, हमरा क्षमा करू।", "ऐ अल्लाह, हम अहाँक एहि दयाक द्वारा प्रार्थना करैत छी जे हमरा क्षमा करी।", "इफ्तार पर-अब्दुल्ला इब्न अम्र (रा.) ई दुआ बनौलनि; इफ्तार पर उपवास करयवला व्यक्तिक दुआ अस्वीकार नहि कयल जाइत अछि।", "हदीस-इफ्तारक समय उपवास करयवला व्यक्तिक दुआ अस्वीकार नहि कयल जाइत अछि।"),
        "dua_inni_saim" to DuaText("जखन उपवास करैत समय उत्तेजित होइत अछि", "हम व्रत करैत छी, हम व्रत करैत छी।", "जखन व्रत करैत काल कोनो व्यक्ति अहाँक अपमान करैत अछि अथवा अहाँ सँ झगड़ा करैत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथिः उपवास एकटा ढाल अछि, तेँ उपवास करय वला व्यक्तिकेँ अश्लील बात नहि करय चाहिऐ आ ना अज्ञानता सँ काज करय चाहिऐ-जँ कोनो व्यक्ति झगड़ा करैत अछि तँ ई बात दू बेर कहि लिअ।"),
    )
}
